package com.deepank.careerraft.documents;
import com.deepank.careerraft.domain.Job;import org.springframework.stereotype.Service;import java.nio.file.*;import java.util.*;
@Service public class CoverLetterRenderer{private final Path template=Path.of("cover_letter","cover_letter.tex");public Path render(CoverLetter letter,Job job,Path output)throws Exception{String t=Files.readString(template);Map<String,String>r=Map.of("{{NAME}}","Deepank Khera","{{CONTACT}}","+91 7988504810 | deepankkhera.dk201314@gmail.com","{{ROLE}}",escape(job.title()),"{{COMPANY}}",escape(job.company()),"{{BODY}}",toLatex(letter.text()));for(var e:r.entrySet())t=t.replace(e.getKey(),e.getValue());output.toAbsolutePath().getParent().toFile().mkdirs();Path tex=output.resolveSibling(output.getFileName().toString().replaceFirst("\\.pdf$",".tex"));Files.writeString(tex,t);Process p=new ProcessBuilder("latexmk","-pdf","-interaction=nonstopmode","-halt-on-error",tex.getFileName().toString()).directory(tex.getParent().toFile()).redirectErrorStream(true).start();String logs=new String(p.getInputStream().readAllBytes());if(p.waitFor()!=0)throw new IllegalStateException("Cover letter LaTeX compilation failed:\n"+logs.substring(Math.max(0,logs.length()-6000)));Path pdf=tex.resolveSibling(tex.getFileName().toString().replaceFirst("\\.tex$",".pdf"));if(!Files.exists(pdf))throw new IllegalStateException("Cover-letter PDF was not produced");return pdf;}private String toLatex(String s){return String.join("\n\n",Arrays.stream(s.split("\\n\\n")).map(x->"\\\\noindent "+escape(x).replace("\n","\\\\\\\\")).toList());}private String escape(String s){return s.replace("\\\\","\\\\textbackslash{}").replace("&","\\\\&").replace("%","\\\\%").replace("$","\\\\$").replace("#","\\\\#").replace("_","\\\\_").replace("{","\\\\{").replace("}","\\\\}");}}
